def filter_cohort(
    rows: List[Dict[str, Any]],
    config: RankerV2Config,
) -> List[Dict[str, Any]]:
    """Filter rows to the ranker-eligible cohort."""
    cohort = []
    for row in rows:
        # Eligibility check
        if config.require_eligible:
            elig = _sf(row.get("eligible"), 0.0)
            if elig != 1.0:
                continue

        # Top-K by actionable_rank
        rank = _sf(row.get("actionable_rank"), float("nan"))
        if rank != rank or rank > config.cohort_top_n:
            continue

        # Catalyst window gate
        if config.require_catalyst_window:
            ciw = row.get("catalyst_in_window", "")
            if ciw not in ("1", "1.0", 1, 1.0, True):
                # Also check catalyst_days as fallback
                cat_days = _sf(row.get("catalyst_days"), 0.0)
                if cat_days < 1 or cat_days > 120:
                    continue

        cohort.append(row)
    return cohort

def _load_development_stage_overrides() -> Dict[str, str]:
    """Read production_data/development_stage_overrides.json -> {ticker: stage}.

    Returns empty dict on missing file, malformed JSON, or unknown stage values.
    Entries with stages outside DEVELOPMENT_STAGE_VALUES are silently dropped to
    prevent invalid values from leaking into rankings.csv.
    """
    p = Path(__file__).resolve().parent / "production_data" / "development_stage_overrides.json"
    if not p.exists():
        return {}
    try:
        raw = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    entries = raw.get("entries", {}) if isinstance(raw, dict) else {}
    if not isinstance(entries, dict):
        return {}
    out: Dict[str, str] = {}
    for ticker, payload in entries.items():
        if not isinstance(payload, dict):
            continue
        stage = payload.get("stage")
        if isinstance(stage, str) and stage in DEVELOPMENT_STAGE_VALUES:
            out[str(ticker).upper()] = stage
    return out


_DEVELOPMENT_STAGE_OVERRIDES: Dict[str, str] = _load_development_stage_overrides()
